library(openPrimeR)

# 1. Generate Template CSVs
fasta.file <- system.file("extdata", "IMGT_data", "templates", "Homo_sapiens_IGH_functional_exon.fasta", package = "openPrimeR")

if (file.exists(fasta.file)) {
    hdr.structure <- c("ACCESSION", "GROUP", "SPECIES", "FUNCTION")
    seq.df <- read_templates(fasta.file, hdr.structure, delim = "|", id.column = "GROUP")
    
    # Split into two sets and write to CSV
    write.csv(seq.df[1:10, ], "templates_set1.csv", row.names = FALSE)
    write.csv(seq.df[11:20, ], "templates_set2.csv", row.names = FALSE)
} else {
    # Fallback if the specific FASTA is not found
    temp_df <- data.frame(
        ID = c("IGHV1-18*01", "IGHV1-2*02"),
        Sequence = c("", 
                     "